def comprimir(texto):
    if texto == '':
        return ''
    resultado = []
    atual = texto[0]
    cont = 1
    for ch in texto[1:]:
        if ch == atual:
            cont += 1
        else:
            resultado.append(f'{atual}{cont}')
            atual = ch
            cont = 1
    resultado.append(f'{atual}{cont}')
    return ''.join(resultado)
